+import http from "http";
+import { claimNotificationJob, completeJob, failJob } from "./jobs.ts";
+
+const PORT = process.env.API_PORT || 3000;
+
+export const createServer = (): http.Server => {
+  return http.createServer(async (req, res) => {
+    if (req.method === "POST" && req.url === "/notifications/claim") {
+      try {
+        const job = await claimNotificationJob();
+        if (job === null) {
+          res.writeHead(204); // No Content
+          res.end();
+          return;
+        }
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(job));
+      } catch (error) {
+        res.writeHead(500);
+        res.end(JSON.stringify({ error: String(error) }));
+      }
+      return;
+    }
+
+    if (req.method === "POST" && req.url?.startsWith("/notifications/complete/")) {
+      try {
+        const jobId = req.url.split("/").pop();
+        if (!jobId) {
+          res.writeHead(400);
+          res.end(JSON.stringify({ error: "Missing job ID" }));
+          return;
+        }
+        await completeJob(jobId);
+        res.writeHead(200);
+        res.end(JSON.stringify({ status: "completed" }));
+      } catch (error) {
+        res.writeHead(500);
+        res.end(JSON.stringify({ error: String(error) }));
+      }
+      return;
+    }
+
+    if (req.method === "POST" && req.url?.startsWith("/notifications/fail/")) {
+      try {
+        const jobId = req.url.split("/").pop();
+        if (!jobId) {
+          res.writeHead(400);
+          res.end(JSON.stringify({ error: "Missing job ID" }));
+          return;
+        }
+
+        let body = "";
+        req.on("data", (chunk) => {
+          body += chunk.toString();
+        });
+
+        req.on("end", async () => {
+          const { reason } = JSON.parse(body || "{}");
+          await failJob(jobId, reason || "Unknown error");
+          res.writeHead(200);
+          res.end(JSON.stringify({ status: "failed" }));
+        });
+      } catch (error) {
+        res.writeHead(500);
+        res.end(JSON.stringify({ error: String(error) }));
+      }
+      return;
+    }
+
+    res.writeHead(404);
+    res.end(JSON.stringify({ error: "Not found" }));
+  });
+};
+
+export const startServer = (): void => {
+  const server = createServer();
+  server.listen(PORT, () => {
+    console.log(`Notifications API listening on port ${PORT}`);
+  });
+};
