+/**
+ * Client library for the external notifications service to consume jobs.
+ * The notifications service runs this independently and doesn't need database access.
+ */
+
+export interface NotificationJob {
+  id: string;
+  payload: string;
+}
+
+export class NotificationsClient {
+  constructor(private baseUrl: string) {}
+
+  async claimJob(): Promise<NotificationJob | null> {
+    const response = await fetch(`${this.baseUrl}/notifications/claim`, {
+      method: "POST",
+    });
+
+    if (response.status === 204) {
+      return null;
+    }
+
+    if (!response.ok) {
+      throw new Error(`Failed to claim job: ${response.statusText}`);
+    }
+
+    return response.json();
+  }
+
+  async completeJob(jobId: string): Promise<void> {
+    const response = await fetch(`${this.baseUrl}/notifications/complete/${jobId}`, {
+      method: "POST",
+    });
+
+    if (!response.ok) {
+      throw new Error(`Failed to complete job: ${response.statusText}`);
+    }
+  }
+
+  async failJob(jobId: string, reason: string): Promise<void> {
+    const response = await fetch(`${this.baseUrl}/notifications/fail/${jobId}`, {
+      method: "POST",
+      headers: { "Content-Type": "application/json" },
+      body: JSON.stringify({ reason }),
+    });
+
+    if (!response.ok) {
+      throw new Error(`Failed to fail job: ${response.statusText}`);
+    }
+  }
+}
+
+export const runNotificationWorker = async (
+  client: NotificationsClient,
+  handler: (payload: string) => Promise<void>,
+  pollIntervalMs: number = 1000,
+): Promise<void> => {
+  for (;;) {
+    const job = await client.claimJob();
+    if (job === null) {
+      await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
+      continue;
+    }
+
+    try {
+      await handler(job.payload);
+      await client.completeJob(job.id);
+    } catch (error) {
+      await client.failJob(job.id, String(error));
+    }
+  }
+};
